fn days_to_next_sunday(day: &str) -> i8 {
    // Map each day abbreviation to an index: SUN=0, MON=1, ..., SAT=6
    let idx: i8 = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => unreachable!("Invalid day abbreviation"),
    };
    // The next Sunday is 7 days minus the current index away.
    7 - idx
}

